// lib/notifications.ts
import axios from 'axios';

export interface Notification {
  id: number;
  type: string;
  title: string;
  message: string;
  data: any;
  is_read: boolean;
  created_at: string;
  read_at: string | null;
}

export const fetchNotifications = async (page = 1): Promise<{ data: Notification[]; total: number }> => {
  const token = localStorage.getItem('token');
  const res = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/notifications?page=${page}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  // Laravel pagination returns { data, total, ... }
  return {
    data: res.data.data || [],
    total: res.data.total || 0,
  };
};

export const fetchUnreadCount = async (): Promise<number> => {
  const token = localStorage.getItem('token');
  const res = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/notifications/unread-count`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  return res.data.count || 0;
};

export const markAsRead = async (id: number): Promise<void> => {
  const token = localStorage.getItem('token');
  await axios.post(`${process.env.NEXT_PUBLIC_API_URL}/notifications/${id}/read`, {}, {
    headers: { Authorization: `Bearer ${token}` },
  });
};

export const markAllAsRead = async (): Promise<void> => {
  const token = localStorage.getItem('token');
  await axios.post(`${process.env.NEXT_PUBLIC_API_URL}/notifications/mark-all-read`, {}, {
    headers: { Authorization: `Bearer ${token}` },
  });
};